const matchesCategory=e=>exploreCategory==='All'||e.category===exploreCategory||(exploreCategory==='Competitive'&&['SSC','Railway','Police','Banking','Defence','State'].includes(e.category));
const categoriesMenu=()=>`<aside class="catalog-aside"><h3>Exam Categories</h3>${categoryNames.map(c=>`<button class="catalog-category ${exploreCategory===c?'chosen':''}" data-marketcat="${esc(c)}">${esc(c)}<span>›</span></button>`).join('')}<div class="aside-help"><b>Practice smarter</b><p>Exam-wise mocks, detailed analysis and saved progress.</p><button class="${page==='analysis'?'is-active':''}" data-nav="${user?'analysis':'login'}">${user?'View performance →':'Track your progress →'}</button></div></aside>`;
