const card=e=>`<article class="exam ${selected===e.id?'active':''}"><div class="logo">📘</div><h3>${esc(e.name)}</h3><p class="muted">${esc(e.category)}</p><span class="tag ${e.verified?'':'pending'}">${e.verified?'Official details marked verified':'Pattern not verified'}</span><p><button class="button ghost small" data-exam="${e.id}">Explore Tests →</button></p></article>`;
function livePage(){const live=tests.filter(t=>t.type==='Live'&&t.published);shell(`<div class="market-content"><div class="page-hero live-hero"><span class="hero-pill">🔴 LIVE TEST ZONE</span><h1>Live Tests & Free Quizzes</h1><p>Join available live challenges and improve your speed and accuracy.</p></div><div class="live-grid">${live.length?live.map(t=>`<article class="live-card"><span class="red-label">● LIVE</span><h3>${esc(t.title)}</h3><p>${t.question_count} Questions · ${t.minutes} Minutes</p><button data-start="${t.id}">Start Test →</button></article>`).join(''):`<div class="empty-live"><span>📅</span><h2>Next live challenge is being prepared</h2><p>Published live tests will appear here. Meanwhile, explore Full and Mini mocks.</p><button class="series-cta" data-nav="dashboard">Explore Test Series →</button></div>`}</div></div>`)}
function studentDashboard(){if(!user){page='login';return login()}const complete=history.length;const avg=complete?Math.round(history.reduce((a,h)=>a+(h.result?.accuracy||0),0)/complete):0;shell(`<div class="market-content"><div class="page-hero student-hero"><span class="hero-pill">YOUR STUDENT SPACE</span><h1>Welcome back, ${esc(user.name)}! 👋</h1><p>Every question you solve brings your goal one step closer.</p></div><div class="student-stat-grid"><div class="student-stat"><span>✅ Completed tests</span><strong>${complete}</strong></div><div class="student-stat"><span>🎯 Average accuracy</span><strong>${avg}%</strong></div><div class="student-stat"><span>📘 Available exams</span><strong>${exams.length}</strong></div></div><div class="student-actions"><button data-nav="exams">Explore Mock Tests →</button><button data-nav="history">My Tests →</button><button data-nav="analysis">Performance →</button><button data-nav="live">Live Tests →</button></div></div>`)}
function showExams(){if(!user){page='login';return login()}const filtered=exams.filter(e=>matchesCategory(e)&&(!searchTerm||e.name.toLowerCase().includes(searchTerm.toLowerCase())));shell(`<div class="market-content"><div class="page-hero student-hero"><span class="hero-pill">YOUR EXAMS</span><h1>Explore Exam Test Series</h1><p>अपनी परीक्षा चुनें और Full, Mini व अन्य Mock Tests देखें।</p></div><section class="catalog-section" id="catalog"><div class="catalog-title"><h2>Explore Mock Test Series</h2><p>अपने परीक्षा के अनुसार Full और Mini Mock चुनें</p></div><div class="catalog-wrap">${categoriesMenu()}<div class="catalog-results"><div class="catalog-tools"><b>${exploreCategory==='All'?'All Exams':esc(exploreCategory)}</b><span>${filtered.length} exam series</span></div><div class="series-grid">${filtered.map(seriesCard).join('')||'<div class="panel empty">No exam series found for this category.</div>'}</div></div></div></section></div>`)}

function syllabusPanel(exam){
 const source=exam.official_url;
 return `<details class="panel"><summary><b>Official syllabus / पाठ्यक्रम</b></summary>${source?`<p>${esc(exam.syllabus)}</p><a href="${esc(source)}" target="_blank" rel="noopener noreferrer">Official syllabus document ↗</a>`:'<p>Official syllabus verification pending.</p>'}</details>`;
}
function showTests(){let e=exams.find(x=>x.id===selected)||exams[0];if(!e)return dashboard();let all=tests.filter(t=>t.published&&t.exam_id===selected&&!t.title.includes('(Sample)')),types=['Full','Mini','Subject','Sectional','Chapter','Topic','PYQ','Live'];const title={'Subject':'Subject Tests','Full':'Full Tests','Mini':'Mini Tests','Sectional':'Sectional Tests','Chapter':'Chapter Tests','Topic':'Topic Tests','PYQ':'Previous Year Questions','Live':'Live Tests'};let filtered=all.filter(t=>t.type===testCategory);shell(`<div class="market-content"><div class="breadcrumbs"><button data-nav="dashboard">Home</button> / Test Series / ${esc(e.name)}</div><div class="series-head"><div class="series-emblem large">${esc(badgeLetters(e.name))}</div><div><span class="tag">${esc(e.category)}</span><h1>${esc(e.name)} Mock Test Series</h1><p>${all.filter(t=>t.published).length} ready · ${all.length} listed · Full / Mini mock tests</p></div></div>${syllabusPanel(e)}<div class="mock-quick-links"><button data-type="Full">Full Mocks (${all.filter(t=>t.type==='Full').length})</button><button data-type="Mini">Mini Mocks (${all.filter(t=>t.type==='Mini').length})</button></div><div class="detail-layout"><div class="detail-menu">${types.map(k=>`<button class="${testCategory===k?'chosen':''}" data-type="${k}">${esc(title[k])}<span>${all.filter(t=>t.type===k).length}</span></button>`).join('')}</div><section class="detail-results"><div class="detail-filter"><h2>${esc(title[testCategory])} (${filtered.length})</h2><select id="examSelect" class="field">${exams.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${filtered.map((t,i)=>`<article class="test-detail-card"><div class="test-detail-main"><div><span class="test-number">${i+1}</span><span class="tag">${esc(t.type)}</span> <span class="mock-availability ${t.published?'ready':'pending'}">${t.published?'Available Now':'Coming Soon'}</span></div><h3>${esc(t.title)}</h3><p>▤ ${t.question_count} Questions <span>◷ ${t.minutes} Mins</span><span>★ ${+(t.question_count*t.positive).toFixed(2)} Marks</span></p><p class="muted">Correct +${t.positive} &nbsp; Wrong −${t.negative}</p>${t.sections?.length?`<small class="muted">${t.sections.map(x=>esc(x.topic)+' ('+x.count+')').join(' • ')}</small>`:''}</div>${t.published?`<button class="series-cta" data-start="${t.id}">Start Test →</button>`:`<span class="mock-pending-button" title="Verified question bank required">Coming Soon</span>`}</article>`).join('')||'<div class="panel empty">इस श्रेणी में अभी कोई mock प्रकाशित नहीं हुआ है।</div>'}</section></div></div>`) }
function authPromo(){return `<div class="login-promo"><span>✦ EXAMNOVA PLUS</span><h2>One place to prepare for every exam</h2><p>Mock tests · Detailed results · Progress tracking · Smart practice</p><div class="promo-symbol">◎</div><strong>Start your preparation with confidence.</strong></div>`}
function login(){shell(`<div class="login-layout"><div class="login-form"><button class="back-link" data-nav="dashboard">← Back to Test Series</button><h1>Login to ExamNova</h1><p>अपने mock-site email और password से login करें। Owner account से Owner Control खुलेगा।</p><form id="loginForm"><label>Email address</label><input class="field" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label>Password</label><input class="field" name="password" type="password" autocomplete="current-password" required placeholder="Enter password"><button class="series-cta full" type="submit">Login</button></form><div class="auth-switch">Don't have an account? <button type="button" data-nav="register">Create Account →</button></div></div>${authPromo()}</div>`)}
function register(){shell(`<div class="login-layout"><div class="login-form"><button class="back-link" data-nav="dashboard">← Back to Test Series</button><h1>Create your ExamNova Account</h1><p>Register to save mock test scores and track progress.</p><form id="registerForm"><label>Your name</label><input class="field" name="name" autocomplete="name" required minlength="2" placeholder="Full name"><label>Email address</label><input class="field" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label>Password (8 or more characters)</label><input class="field" name="password" type="password" autocomplete="new-password" required minlength="8" placeholder="Create password"><button class="series-cta full" type="submit">Create Account</button></form><div class="auth-switch">Already have an account? <button type="button" data-nav="login">Login →</button></div></div>${authPromo()}</div>`)}

const fmt=ms=>{let s=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
function showInstructions(){const t=tests.find(x=>x.id===pendingTest);if(!t)return showTests();shell(`<div class="panel instructions"><span class="tag">TEST INSTRUCTIONS / परीक्षा निर्देश</span><h1>${esc(t.title)}</h1><div class="test-meta"><span>📝 ${t.question_count} questions</span><span>⏱ ${t.minutes} minutes</span><span>🎯 ${+(t.question_count*t.positive).toFixed(2)} marks</span><span>+${t.positive} / −${t.negative}</span></div><h3>परीक्षा शुरू करने से पहले पढ़ें</h3><ol><li>प्रत्येक प्रश्न का एक सही उत्तर चुनें। उत्तर चुनते ही server पर save होगा।</li><li>Save & Next, Previous और question palette से सवाल बदल सकते हैं।</li><li>Mark for Review से प्रश्न दोबारा देखने के लिए चिह्नित करें; उत्तर दिया है तो वह मूल्यांकन में गिना जाएगा।</li><li>${t.behavior?.timerMode==='sectional'?'हर section का अलग timer है। Section का समय खत्म होने पर उसमें वापस नहीं जा सकेंगे।':'पूरे टेस्ट के लिए एक timer रहेगा।'}</li><li>Timer समाप्त होने पर test अपने-आप submit हो जाएगा। Test बंद कर देने पर भी timer चलता रहेगा।</li><li>Green = Answered, Orange = Visited, Purple = Review, Grey = Not Visited.</li></ol>${t.sections?.length?`<h3>Section plan</h3><p>${t.sections.map(x=>esc(x.topic)+' — '+x.count).join(' • ')}</p>`:''}<div class="row"><button class="button ghost" data-act="instructionsBack">← Back</button><button class="button" data-act="beginTest">I Understand • Start Test →</button></div></div>`)}
function currentSectionInfo(){if(!attempt?.test?.behavior||attempt.test.behavior.timerMode!=='sectional')return null;let elapsed=(Date.now()-(attempt.deadline-attempt.test.minutes*60000))/60000,cumulative=0;const plan=attempt.test.behavior.sectionRules||[];for(let i=0;i<plan.length;i++){cumulative+=plan[i].minutes;if(elapsed<cumulative)return {index:i,remaining:(cumulative-elapsed)*60000,topic:plan[i].topic};}return {index:plan.length,remaining:0,topic:'Completed'};}
function sectionOfQuestion(i){if(!attempt?.test?.sections)return -1;let sum=0;for(let n=0;n<attempt.test.sections.length;n++){sum+=attempt.test.sections[n].count;if(i<sum)return n}return -1;}
function allowedQuestion(i){const info=currentSectionInfo();if(info&&sectionOfQuestion(i)!==info.index)return false;const nav=attempt?.test?.behavior?.navigation;if(nav==='forward_only'&&!info&&i<index)return false;return true;}
function showAttempt(){if(!attempt)return;void api(`attempts/${attempt.id}/answer`,'POST',{questionId:attempt.questions[index]?.id,focus:true}).catch(()=>{});const sectionInfo=currentSectionInfo();if(sectionInfo&&sectionOfQuestion(index)!==sectionInfo.index){const first=attempt.questions.findIndex((x,i)=>sectionOfQuestion(i)===sectionInfo.index);if(first>=0)index=first;}let q=attempt.questions[index],ans=attempt.answers[q.id],review=attempt.review||{};visited[q.id]=true;let unique=[...new Set(attempt.questions.map(x=>x.topic))],counts={answered:0,unanswered:0,review:0,unvisited:0};const status=x=>{if(review[x.id])return attempt.answers[x.id]!==undefined?'review-answered':'review';if(attempt.answers[x.id]!==undefined)return 'answered';return visited[x.id]?'unanswered':'unvisited'};for(const x of attempt.questions){let st=status(x);if(st==='review-answered')counts.answered++;else if(st==='review')counts.review++;else counts[st]++}shell(`<div class="row between"><div><span class="tag">${sectionInfo?"SECTIONAL TIMER MODE":"EXAM MODE"}</span><h2>${esc(attempt.test.title)}</h2>${sectionInfo?`<p class="section-timer-info">🔒 Current: ${esc(sectionInfo.topic)} · Section time left <strong id="sectionClock">${fmt(sectionInfo.remaining)}</strong> · Completed sections locked</p>`:""}</div><div class="countdown-box">⏱ Time left <strong id="countdown">${fmt(attempt.deadline-Date.now())}</strong></div></div><div class="section-bar">${unique.map(topic=>`<button class="section-btn ${q.topic===topic?'selected':''}" data-section="${esc(topic)}" ${sectionInfo&&unique.indexOf(topic)!==sectionInfo.index?"disabled":""}>${esc(topic)} <small>${attempt.questions.filter(x=>x.topic===topic).length}</small></button>`).join('')}</div><div class="examui"><div class="panel question-panel"><div class="row between"><span class="tag">${esc(q.topic)}</span><strong>Question ${index+1} of ${attempt.questions.length}</strong></div><h2 class="question-stem">${esc(q.stem)}</h2>${q.options.map((o,i)=>`<button class="option ${ans===i?'selected':''}" data-answer="${i}"><span class="option-letter">${String.fromCharCode(65+i)}</span> ${esc(o)}</button>`).join('')}<div class="question-actions"><button class="button ghost" data-answer="clear">Clear Response</button><button class="button ghost" data-review="1" ${attempt.test.behavior?.reviewPolicy==='disabled'?"disabled":""}>${review[q.id]?'Remove Review':'Mark for Review & Next'}</button><button class="button ghost" data-move="-1">← Previous</button><button class="button" data-move="1">Save & Next →</button></div></div><div class="panel palette-panel"><h3>Question Palette</h3><div class="status-mini"><span><i class="status-dot answered"></i>Answered ${counts.answered}</span><span><i class="status-dot unanswered"></i>Not Answered ${counts.unanswered}</span><span><i class="status-dot review"></i>Review ${counts.review}</span><span><i class="status-dot unvisited"></i>Not Visited ${counts.unvisited}</span></div><div class="palette">${attempt.questions.map((x,i)=>`<button class="${status(x)} ${index===i?'active':''}" data-jump="${i}" ${sectionInfo&&sectionOfQuestion(i)!==sectionInfo.index?"disabled":""} title="${esc(x.topic)}">${i+1}</button>`).join('')}</div><p class="smalltext muted">+${attempt.test.positive} correct · −${attempt.test.negative} wrong</p><button class="button danger" data-act="submit">Submit Test</button></div></div>`);clearInterval(timer);timer=setInterval(()=>{let el=$('#countdown');if(el)el.textContent=fmt(attempt.deadline-Date.now());const info=currentSectionInfo(),secEl=$('#sectionClock');if(secEl&&info)secEl.textContent=fmt(info.remaining);if(info&&sectionOfQuestion(index)!==info.index&&info.index<attempt.test.sections.length){index=attempt.questions.findIndex((x,i)=>sectionOfQuestion(i)===info.index);render();return;}if(document.visibilityState==='visible'&&Date.now()<attempt.deadline&&Math.floor(Date.now()/1000)%5===0)void api(`attempts/${attempt.id}/answer`,'POST',{questionId:attempt.questions[index]?.id,focus:true}).catch(()=>{});if(Date.now()>=attempt.deadline){clearInterval(timer);submitTest(true)}},1000)}
function showResult(){let r=result;if(!r)return showHistory();const weak=Object.entries(r.topics).filter(([t,x])=>x.correct<x.total).sort((a,b)=>(a[1].correct/a[1].total)-(b[1].correct/b[1].total));const renderQuestion=(q,i)=>{const isWrong=q.selected!==q.correctIndex;return `<article class="panel review-question"><div class="review-question-head"><span class="topic-chip">${esc(q.topic)}</span><span class="${q.selected===null?'review-skip':isWrong?'review-wrong':'review-right'}">${q.selected===null?'Skipped':isWrong?'Incorrect':'Correct'}</span></div><h3>${i+1}. ${esc(q.stem)}</h3><p class="muted">⏱ ${q.timeMs==null?'Timing unavailable (older attempt)':(q.timeMs/1000).toFixed(1)+' seconds'}</p><div class="review-options">${q.options.map((opt,j)=>`<div class="review-option ${j===q.correctIndex?'option-right':j===q.selected?'option-wrong':''}"><div class="review-option-title"><b>${'ABCD'[j]}.</b> ${esc(opt)} ${j===q.correctIndex?'<strong>✓ सही उत्तर</strong>':j===q.selected?'<strong>✕ आपका चयन</strong>':''}</div><div class="option-reason">${q.optionExplanations?.[j]?.trim()?esc(q.optionExplanations[j]):j===q.correctIndex?(q.explanation?.trim()?esc(q.explanation):'इस विकल्प की विस्तृत व्याख्या अभी उपलब्ध नहीं है।'):'इस विकल्प की अलग व्याख्या अभी जोड़ी नहीं गई है।'}</div></div>`).join('')}</div>${q.revisionNotes?.trim()?`<div class="revision-note"><h4>📘 Related Revision Notes</h4><p>${esc(q.revisionNotes)}</p></div>`:''}</article>`};shell(heading('Detailed Result Analysis','हर उत्तर की जाँच, चारों विकल्पों का कारण और topic-wise revision')+`<div class="panel"><div class="score">${r.score.toFixed(2)} / ${r.maxMarks.toFixed(2)}</div><div class="row"><span class="good">✔ Correct: ${r.correct}</span><span class="bad">✕ Wrong: ${r.wrong}</span><span>○ Skipped: ${r.skipped}</span><span>Accuracy: ${r.accuracy}%</span></div><p class="muted">Marking +${r.positive} / −${r.negative} · Rank या percentile का अनुमान नहीं लगाया गया है।</p><button class="button ghost" data-nav="history">Test History</button></div>${resultCharts(r)}<h2>📊 Topic Breakdown</h2><div class="grid">${Object.entries(r.topics).map(([topic,x])=>`<div class="stat"><span>${esc(topic)}</span><strong>${x.correct}/${x.total}</strong><small>${Math.round(100*x.correct/x.total)}% सही</small></div>`).join('')}</div><h2>🎯 Weak Topics & Revision</h2>${weak.length?`<div class="grid">${weak.map(([topic,x])=>`<div class="panel"><h3>${esc(topic)}</h3><p>${x.total-x.correct} प्रश्न गलत या छोड़े गए</p><p class="muted">नीचे इसी topic के प्रश्न, explanation और उपलब्ध notes देखें।</p></div>`).join('')}</div>`:'<p class="panel">सभी प्रश्न सही हैं — बढ़िया अभ्यास!</p>'}<h2>📖 Question-wise Detailed Solutions</h2><p class="muted">चारों विकल्पों का कारण केवल तभी दिखेगा जब Admin ने verify करके दर्ज किया हो।</p>${r.review.map(renderQuestion).join('')}`)}
function showHistory(){shell(heading('My Test History','आपके सभी attempts · कभी भी पूरा result और solutions खोलें')+(user?`<div class="panel"><table class="table"><thead><tr><th>Test</th><th>Score</th><th>Accuracy</th><th>Date</th><th>Analysis</th></tr></thead><tbody>${history.map(h=>`<tr><td>${esc(h.title)}</td><td>${h.result.score}/${h.result.maxMarks}</td><td>${h.result.accuracy}%</td><td>${new Date(h.submitted_at).toLocaleString('en-IN')}</td><td><button class="button ghost" data-resume="${h.id}">View Full Result →</button></td></tr>`).join('')}</tbody></table>${!history.length?'<div class="empty">No completed tests yet.</div>':''}</div>`:'<div class="notice">Please login to see your history.</div>'))}
function analysis(){const total=history.reduce((n,x)=>n+x.result.total,0),correct=history.reduce((n,x)=>n+x.result.correct,0),attempted=history.reduce((n,x)=>n+x.result.correct+x.result.wrong,0);shell(heading('Performance Analysis','Your test-wise performance and accuracy')+`<div class="stats"><div class="stat"><span>Completed</span><strong>${history.length}</strong></div><div class="stat"><span>Questions</span><strong>${total}</strong></div><div class="stat"><span>Attempted</span><strong>${attempted}</strong></div><div class="stat"><span>Accuracy</span><strong>${attempted?(100*correct/attempted).toFixed(1):0}%</strong></div></div><button class="button ghost" data-nav="history">Detailed History</button>`)}
let dailyData=[],adminQuestions=[];const examOpts=()=>exams.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');
function dailyPanel(){return `<section class="panel" id="daily-control"><h2>Automatic Mock Draft Studio</h2><p>हर exam के लिए दो Full और दो Mini draft slots हैं। Official syllabus वाले exams में AI questions भरता है। Questions सहित preview करें → edit/update/delete करें → review करके publish करें।</p><div id="auto-studio">Loading drafts…</div></section>`}
function showAdmin(){if(user?.role!=='admin'){page='login';return login()}shell(`<section class="panel"><h1>Mock Test Manager</h1><p>Exam और Full / Mini / Subject चुनें → questions paste करें → preview / edit → publish.</p><button class="button" data-add-exam>＋ Add Exam</button> <button class="button" data-new-manual>＋ Create Mock</button> <button class="button ghost" data-bulk-paste>Paste Questions into Mock</button></section><section class="panel"><h2>My Mocks</h2><div id="auto-studio"></div></section>`)}
function render(){if(page==='dashboard')dashboard();else if(page==='exams')showExams();else if(page==='live')livePage();else if(page==='student')studentDashboard();else if(page==='tests')showTests();else if(page==='login')login();else if(page==='register')register();else if(page==='attempt')showAttempt();else if(page==='instructions')showInstructions();else if(page==='result')showResult();else if(page==='history')showHistory();else if(page==='analysis')analysis();else if(page==='admin')showAdmin()}
const reload=async()=>{const [e,t,status]=await Promise.all([api('exams'),api('tests'),api('status')]);exams=e.exams;tests=t.tests;window.examNovaBuild=status.build;window.examNovaCounts={server:status.total,loaded:tests.length};if(!exams.some(x=>x.id===selected))selected=exams[0]?.id;if(token){
 try{user=(await api('me')).user}
 catch(err){console.warn('Session verification failed:',err.message);token='';sessionStorage.removeItem('en_token');user=null;history=[];incomplete=[]}
 if(user){
  if(user.role==='admin'){
   try{dailyData=(await api('admin/daily')).queue}catch(err){console.warn('Admin draft queue unavailable:',err.message);dailyData=[]}
   try{adminQuestions=(await api('admin/questions')).questions}catch(err){console.warn('Admin questions unavailable:',err.message);adminQuestions=[]}
  }
  try{history=(await api('history')).history}catch(err){console.warn('History unavailable:',err.message);history=[]}
  try{incomplete=(await api('incomplete')).attempts}catch(err){console.warn('Incomplete attempts unavailable:',err.message);incomplete=[]}
 }
}render()};
const submitTest=async(auto=false)=>{if(!attempt)return;if(!auto&&!confirm('Submit test now?'))return;try{let j=await api('attempts/'+attempt.id+'/submit','POST',{});result=j.result;attempt=null;clearInterval(timer);page='result';history=(await api('history')).history;render()}catch(e){alert(e.message)}};
root.addEventListener('click',async e=>{let b=e.target.closest('[data-marketcat],[data-nav],[data-exam],[data-filter],[data-type],[data-start],[data-answer],[data-move],[data-review],[data-jump],[data-section],[data-resume],[data-act]');if(!b)return;try{if(b.dataset.marketcat){exploreCategory=b.dataset.marketcat;page=user?'exams':'login';render()}else if(b.dataset.nav){const next=b.dataset.nav;if(next==='features'||next==='about'){page='dashboard';render();document.getElementById(next)?.scrollIntoView({behavior:'smooth'});}else{if(next==='admin'&&user?.role==='admin'){try{dailyData=(await api('admin/daily')).queue}catch(err){console.warn('Draft Queue:',err.message);dailyData=[]}try{adminQuestions=(await api('admin/questions')).questions}catch(err){console.warn('Question Bank:',err.message);adminQuestions=[]}}page=(!user&&['student','exams','tests','live','history','analysis','admin'].includes(next))?'login':next;render()}}else if(b.dataset.exam){selected=+b.dataset.exam;testCategory='Full';page=user?'tests':'login';render()}else if(b.dataset.type){testCategory=b.dataset.type;render()}else if(b.dataset.filter!==undefined){const cat=b.dataset.filter;$('#cards').innerHTML=exams.filter(x=>!cat||x.category===cat).map(card).join('')}else if(b.dataset.start){if(!tests.find(t=>t.id===+b.dataset.start)?.published){alert('Question bank verification pending. This test is not available yet.');return}if(!user){page='login';return render()}pendingTest=+b.dataset.start;page='instructions';render()}else if(b.dataset.answer!==undefined){let q=attempt.questions[index],val=b.dataset.answer==='clear'?null:+b.dataset.answer;await api(`attempts/${attempt.id}/answer`,'POST',{questionId:q.id,answer:val});if(val===null)delete attempt.answers[q.id];else attempt.answers[q.id]=val;render()}else if(b.dataset.review){let q=attempt.questions[index],v=!attempt.review[q.id];await api(`attempts/${attempt.id}/answer`,'POST',{questionId:q.id,review:v});attempt.review[q.id]=v;if(v&&index<attempt.questions.length-1&&allowedQuestion(index+1))index++;render()}else if(b.dataset.section){let i=attempt.questions.findIndex(x=>x.topic===b.dataset.section);if(i>=0&&allowedQuestion(i)){index=i;render()}}else if(b.dataset.move){const target=Math.max(0,Math.min(attempt.questions.length-1,index+Number(b.dataset.move)));if(allowedQuestion(target))index=target;render()}else if(b.dataset.jump){if(allowedQuestion(+b.dataset.jump))index=+b.dataset.jump;render()}else if(b.dataset.act==='search'){searchTerm=$('#siteSearch')?.value.trim()||'';page=user?'exams':'login';render()}else if(b.dataset.act==='submit')submitTest();else if(b.dataset.act==='instructionsBack'){page='tests';render()}else if(b.dataset.act==='beginTest'){let j=await api('attempts','POST',{testId:pendingTest});attempt=await api('attempts/'+j.id);index=0;visited={};page='attempt';render()}else if(b.dataset.resume){attempt=await api('attempts/'+Number(b.dataset.resume));index=0;visited={};page=attempt.done?'result':'attempt';if(attempt.done)result=attempt.result;render();}else if(b.dataset.act==='logout'){await api('logout','POST',{});token='';sessionStorage.removeItem('en_token');user=null;history=[];page='dashboard';render()}}catch(e){alert(e.message)}});
root.addEventListener('click',async e=>{const b=e.target.closest('[data-daily-refresh],[data-daily-edit]');if(!b)return;try{if(b.dataset.dailyRefresh!==undefined){await api('admin/daily/generate','POST',{});dailyData=(await api('admin/daily')).queue;render();return}const t=dailyData.find(x=>x.id===Number(b.dataset.dailyEdit))||studioState?.mocks.find(x=>x.id===Number(b.dataset.dailyEdit));if(!t)return;const title=prompt('Mock title',t.title);if(title===null)return;const minutes=prompt('Duration (minutes)',t.minutes);if(minutes===null)return;const positive=prompt('Correct answer marks',t.positive);if(positive===null)return;const negative=prompt('Wrong answer deduction',t.negative);if(negative===null)return;await api('admin/daily/'+t.id,'PATCH',{title,minutes:+minutes,positive:+positive,negative:+negative});await reload()}catch(err){alert(err.message)}});
root.addEventListener('click',async e=>{if(!e.target.closest('[data-readiness]'))return;try{const status=await api('admin/readiness');const pending=status.tests.filter(x=>!x.ready);let msg=`Total test records: ${status.tests.length}\nReady to publish: ${status.tests.filter(x=>x.ready).length}\nPending: ${pending.length}\n\n`;msg+=pending.slice(0,25).map(t=>t.exam+' - '+t.title+': '+t.coverage.filter(x=>x.missing).map(x=>x.topic+' '+x.missing+' missing').join(', ')).join('\n');alert(msg)}catch(err){alert(err.message)}});
root.addEventListener('click',async e=>{const btn=e.target.closest('[data-publish]');if(!btn)return;const next=btn.dataset.current!=='1';if(!confirm(`${next?'Publish':'Unpublish'} this mock?`))return;try{await api('admin/tests/'+btn.dataset.publish,'PATCH',{published:next});await reload()}catch(err){const status=await api('admin/readiness').catch(()=>null);const detail=status?.tests?.find(x=>x.id===Number(btn.dataset.publish));alert(err.message+(detail?'\n\n'+detail.coverage.map(x=>`${x.topic}: ${x.verified}/${x.required} verified; ${x.missing} missing`).join('\n'):''))} });
root.addEventListener('keydown',e=>{if(e.target.id==='siteSearch'&&e.key==='Enter'){searchTerm=e.target.value.trim();page=user?'exams':'login';render()}});
root.addEventListener('change',e=>{if(e.target.id==='examSelect'){selected=+e.target.value;render()}});
root.addEventListener('submit',async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));try{if(f.id==='loginForm'){let j=await api('login','POST',d);token=j.token;sessionStorage.setItem('en_token',token);user=j.user;page=user.role==='admin'?'admin':'student';history=[];incomplete=[];try{history=(await api('history')).history}catch(err){console.warn('History unavailable:',err.message)}try{incomplete=(await api('incomplete')).attempts}catch(err){console.warn('Incomplete attempts unavailable:',err.message)}}else if(f.id==='registerForm'){await api('register','POST',d);alert('Account created. Please log in.');page='login'}else if(f.id==='newExam'){await api('admin/exams','POST',d);alert('Exam added')}else if(f.id==='newQuestion'){await api('admin/questions','POST',{examId:+d.examId,topic:d.topic,stem:d.stem,options:[d.opt0,d.opt1,d.opt2,d.opt3],correctIndex:+d.correctIndex,explanation:d.explanation,optionExplanations:[d.reason0,d.reason1,d.reason2,d.reason3],revisionNotes:d.revisionNotes,verified:d.verified==='on'});alert('Question saved')}else if(f.id==='editBehavior'){const rules=d.sectionRules?.trim()?d.sectionRules.trim().split(/\r?\n/).map(line=>{const m=line.match(/^(.*?):\s*(\d+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)$/);if(!m)throw Error('Use Topic: minutes | correct | wrong');return {topic:m[1].trim(),minutes:+m[2],positive:+m[3],negative:+m[4]}}):[];await api('admin/tests/'+Number(d.testId)+'/behavior','PATCH',{behavior:{timerMode:d.timerMode,navigation:d.navigation,reviewPolicy:d.reviewPolicy,sectionRules:rules}});alert('Test behavior saved.')}else if(f.id==='newTest'){await api('admin/tests','POST',{examId:+d.examId,title:d.title,type:d.type,questionCount:+d.questionCount,minutes:+d.minutes,positive:+d.positive,negative:+d.negative,published:d.published==='on',behavior:{timerMode:d.timerMode,navigation:d.navigation,reviewPolicy:d.reviewPolicy,shuffle:d.shuffle==='on',sectionRules:d.sectionRules?.trim()?d.sectionRules.trim().split(/\r?\n/).map(line=>{let m=line.match(/^(.*?):\s*(\d+)\s*\|\s*([\d.]+)\s*\|\s*([\d.]+)\s*$/);if(!m)throw Error('Use Topic: minutes | positive | negative');return {topic:m[1].trim(),minutes:+m[2],positive:+m[3],negative:+m[4]}}):[]},sections:d.sectionPlan?.trim()?d.sectionPlan.trim().split(/\r?\n/).map(line=>{let m=line.match(/^(.*?):\s*(\d+)\s*$/);if(!m)throw Error('Use Topic: count on each line');return {topic:m[1].trim(),count:+m[2]}}):[]});alert('Test saved')}await reload()}catch(ex){alert(ex.message)}});
startFromJPOwner().catch(e=>shell(`<h2>Backend connection failed</h2><p class="notice">Start the Node.js server using <code>npm start</code>. ${esc(e.message)}</p>`));

// Active admin control section stays highlighted after click.
