root.addEventListener('click',async event=>{const b=event.target.closest('[data-question-edit],[data-question-refresh]');if(!b)return;try{
 if(b.dataset.questionRefresh!==undefined){adminQuestions=(await api('admin/questions')).questions;render();return}
 const q=adminQuestions.find(x=>x.id===Number(b.dataset.questionEdit));if(!q)return;
 const stem=prompt('Question (Cancel to stop)',q.stem);if(stem===null)return;
 const topic=prompt('Topic / Section',q.topic);if(topic===null)return;
 const options=[];for(let i=0;i<4;i++){const o=prompt('Option '+String.fromCharCode(65+i),q.options[i]);if(o===null)return;options.push(o)}
 const correctIndex=prompt('Correct option: 1=A, 2=B, 3=C, 4=D',q.correct_index+1);if(correctIndex===null)return;
 const explanation=prompt('Correct answer explanation',q.explanation||'');if(explanation===null)return;
 const reason=JSON.parse(q.option_explanations_json||'[]');const reasons=[];
 for(let i=0;i<4;i++){const r=prompt('Why option '+String.fromCharCode(65+i)+' is right/wrong?',reason[i]||'');if(r===null)return;reasons.push(r)}
 const revisionNotes=prompt('Related revision notes',q.revision_notes||'');if(revisionNotes===null)return;
 const verified=confirm('Have you checked this question against a reliable source and all four explanations? OK = Verified, Cancel = Keep Draft');
 await api('admin/questions/'+q.id,'PATCH',{stem,topic,options,correctIndex:Number(correctIndex)-1,explanation,optionExplanations:reasons,revisionNotes,verified});adminQuestions=(await api('admin/questions')).questions;render();alert('Question updated successfully.');
 }catch(err){alert(err.message)} });

let studioState=null,studioPreview=null;
async function refreshStudio(){if(page!=='admin'||user?.role!=='admin')return;try{studioState=await api('admin/studio');const box=document.getElementById('auto-studio');if(!box)return;box.innerHTML=studioState.mocks.length?studioState.mocks.map(t=>`<article class="panel"><b>${esc(t.title)}</b><p>${esc(t.exam_name)} · ${esc(t.type)} · ${t.generated}/${t.question_count} questions · ${t.minutes} min · ${t.published?'Published':'Draft'}</p><button class="button ghost" data-auto-preview="${t.id}">Preview / Edit</button> ${!t.published?`<button class="button ghost" data-bulk-paste data-target-mock="${t.id}">Add Questions</button> <button class="button ghost" data-daily-edit="${t.id}">Settings</button> <button class="button" data-auto-publish="${t.id}" ${t.ready?'':'disabled'}>Review & Publish</button> <button class="button ghost" data-auto-delete="${t.id}">Delete Mock</button>`:`<button class="button ghost" data-publish="${t.id}" data-current="1">Unpublish</button>`}</article>`).join(''):'<p>अभी कोई mock नहीं है। ऊपर Paste Questions से अपना पहला mock बनाएं।</p>'}catch(e){const box=document.getElementById('auto-studio');if(box)box.textContent=e.message}}

function questionDialog(q,testId){const dialog=document.createElement('dialog');dialog.style.cssText='width:min(900px,95vw);max-height:90vh;overflow:auto;border-radius:16px';dialog.innerHTML=`<h2>Edit Question</h2><p>Question, four options, correctIndex (0=A … 3=D), explanations और notes update करें।</p><form><textarea class="field" name="json" rows="24"></textarea><p class="muted" data-error></p><button class="button">Save Question</button> <button type="button" class="button ghost" data-close>Cancel</button></form>`;dialog.querySelector('textarea').value=JSON.stringify({topic:q.topic,stem:q.stem,options:q.options,correctIndex:q.correct_index,explanation:q.explanation,optionExplanations:q.optionExplanations,revisionNotes:q.revisionNotes,verified:false},null,2);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const v=JSON.parse(dialog.querySelector('textarea').value);await api('admin/questions/'+q.id,'PATCH',v);dialog.close();await previewMock(testId)}catch(err){dialog.querySelector('[data-error]').textContent=err.message}};dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal()}
async function previewMock(id){studioPreview?.remove();const data=await api('admin/studio/'+id),t=studioState.mocks.find(x=>x.id===id);const d=document.createElement('dialog');studioPreview=d;d.style.cssText='width:min(1050px,96vw);max-height:90vh;overflow:auto;border-radius:16px';d.innerHTML=`<button class="button ghost" data-close>Close Preview</button><h2>${esc(t?.title||'Mock')}</h2><p>${data.questions.length}/${t?.question_count} questions · Check pattern, answers and explanations before publishing.</p>${data.questions.map((q,i)=>`<article class="panel"><b>${i+1}. [${esc(q.topic)}] ${esc(q.stem)}</b><ol type="A">${q.options.map((o,n)=>`<li>${esc(o)} ${n===q.correct_index?'✅':''}<p>${esc(q.optionExplanations[n]||'')}</p></li>`).join('')}</ol><p>${esc(q.explanation)}</p><p><b>Revision:</b> ${esc(q.revisionNotes)}</p>${!t?.published?`<button class="button ghost" data-edit="${q.id}">Edit / Update</button> `:''}</article>`).join('')||'<p>इस mock में अभी questions नहीं हैं।</p>'}`;d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();d.onclick=async e=>{const b=e.target.closest('[data-edit],[data-delete]');if(!b)return;try{if(b.dataset.edit){questionDialog(data.questions.find(q=>q.id===+b.dataset.edit),id)}else if(confirm('Delete this question? Adjust the question count and section count in Settings before publishing.')){await api('admin/studio/'+id+'/questions/'+b.dataset.delete,'DELETE');await previewMock(id);await refreshStudio()}}catch(err){alert(err.message)}};document.body.append(d);d.showModal()}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-auto-refresh],[data-auto-toggle],[data-auto-preview],[data-auto-retry],[data-auto-publish],[data-auto-delete],[data-auto-pattern]');if(!b)return;try{
 if(b.hasAttribute('data-auto-toggle'))await api('admin/studio/settings','POST',{enabled:!studioState.enabled});
 if(b.dataset.autoPreview)return await previewMock(+b.dataset.autoPreview);
 if(b.dataset.autoRetry)await api('admin/studio/retry','POST',{id:+b.dataset.autoRetry});
 if(b.dataset.autoDelete&&confirm('Delete this unpublished mock permanently?'))await api('admin/studio/'+b.dataset.autoDelete,'DELETE');
 if(b.dataset.autoPublish&&confirm('मैंने सभी questions, answers, explanations और इस exam के pattern की जाँच कर ली है। Publish करें?')){await api('admin/studio/'+b.dataset.autoPublish+'/publish','POST',{reviewed:true});await reload()}
 if(b.hasAttribute('data-auto-pattern')){const id=prompt('Exam ID: '+exams.map(x=>x.id+'='+x.name).join(', '));if(!id)return;const t=studioState.mocks.find(x=>x.exam_id===+id&&x.type==='Full');const pattern=prompt('खाली starter mocks के लिए Full pattern JSON: sections, minutes, positive, negative',JSON.stringify({sections:t?.sections||[{topic:'General',count:50}],minutes:t?.minutes||60,positive:t?.positive||1,negative:t?.negative||0}));if(!pattern)return;const syllabus=prompt('इस exam/stage का syllabus, level और exclusions लिखें:','');if(syllabus===null)return;const officialUrl=prompt('Official syllabus document का HTTPS link:','');if(!officialUrl)return;await api('admin/studio/pattern','POST',{examId:+id,pattern:JSON.parse(pattern),syllabus,officialUrl});alert('Pattern saved. Empty starter mocks updated. Drafts with questions are preserved.');}
 await refreshStudio();
}catch(err){alert(err.message)}});
