async function startFromJPOwner(){
 if(new URLSearchParams(location.search).get('view')==='login')page='login';
 const ticket=new URLSearchParams(location.hash.slice(1)).get('jp_control');
 if(ticket){historyReplaceOwnerURL();try{const login=await api('jp-control/exchange','POST',{ticket});token=login.token;sessionStorage.setItem('en_token',token);user=login.user;page='admin'}catch(e){token='';sessionStorage.removeItem('en_token');user=null;page='login';await reload();alert(e.message);return}}
 await reload();
}
function historyReplaceOwnerURL(){window.history.replaceState(null,'',location.pathname+location.search)}

function resultCharts(r){const total=r.total||1,tracked=r.review.some(q=>q.timeMs!=null),max=Math.max(1000,...r.review.map(q=>q.timeMs||0));return `<section class="panel"><h2>📈 Score & Time Insights</h2><div class="stats"><div class="stat"><span>Total elapsed</span><strong>${r.durationMs==null?'—':fmt(r.durationMs)}</strong></div><div class="stat"><span>Tracked question time</span><strong>${tracked?fmt(r.trackedMs||0):'—'}</strong></div><div class="stat"><span>Average / question</span><strong>${tracked?((r.trackedMs||0)/total/1000).toFixed(1)+'s':'—'}</strong></div></div><div style="display:flex;height:24px;border-radius:12px;overflow:hidden;margin:24px 0" aria-label="Correct ${r.correct}, wrong ${r.wrong}, skipped ${r.skipped}"><div style="width:${100*r.correct/total}%;background:#10b981"></div><div style="width:${100*r.wrong/total}%;background:#f43f5e"></div><div style="width:${100*r.skipped/total}%;background:#94a3b8"></div></div><p>🟢 Correct ${r.correct} · 🔴 Wrong ${r.wrong} · ⚪ Skipped ${r.skipped}</p><h3>Question-wise time · hover for seconds</h3>${tracked?`<div style="display:flex;align-items:end;gap:3px;height:155px;overflow-x:auto;padding:8px 0">${r.review.map((q,i)=>`<div title="Q${i+1}: ${((q.timeMs||0)/1000).toFixed(1)}s" style="flex:1;min-width:12px;max-width:45px;height:${Math.max(3,140*(q.timeMs||0)/max)}px;background:${q.selected==null?'#94a3b8':q.selected===q.correctIndex?'#10b981':'#f43f5e'};border-radius:4px 4px 0 0"></div>`).join('')}</div><p class="muted">Left to right: Q1–Q${r.total}. Timing records active question focus; time while disconnected or away may be untracked.</p>`:'<p>इस पुराने attempt में question timing record नहीं हुई थी।</p>'}<h3>Section time & accuracy</h3>${Object.entries(r.topics).map(([topic,x])=>{const rows=r.review.filter(q=>q.topic===topic),ms=rows.reduce((n,q)=>n+(q.timeMs||0),0);return `<div style="margin:18px 0"><b>${esc(topic)}</b><p>${x.correct}/${x.total} correct · ${Math.round(100*x.correct/x.total)}% · ${tracked?fmt(ms):'Timing unavailable'}</p><div style="height:10px;background:#ede9fe;border-radius:8px"><div style="height:100%;width:${100*x.correct/x.total}%;background:linear-gradient(90deg,#7c3aed,#06b6d4);border-radius:8px"></div></div></div>`}).join('')}</section>`}

root.addEventListener('click',async event=>{
 if(!event.target.closest('[data-paste-mock]'))return;
 try{
  const {mocks}=await api('admin/studio');
  const available=mocks.filter(t=>!t.published&&!t.ready&&t.sections.length);
  if(!available.length){alert('No draft mock with an open section.');return}
  const dialog=document.createElement('dialog');
  dialog.style.cssText='width:min(680px,95vw);max-height:90vh;overflow:auto';
  dialog.innerHTML=`<h2>Paste Question + Answer</h2><form>
   <label>Draft mock <select name="test" class="field">${available.map(t=>`<option value="${t.id}">${esc(t.exam_name)} · ${esc(t.title)}</option>`).join('')}</select></label>
   <label>Section <select name="topic" class="field"></select></label>
   <label>Question <textarea name="stem" class="field" required></textarea></label>
   <label>Answer <input name="answer" class="field"></label>
   <button type="button" class="button ghost" data-generate>Make options with AI</button>
   <p>Review the options below. If you already have options, enter them directly.</p>
   ${Array.from({length:4},(_,i)=>`<label>Option ${'ABCD'[i]} <input name="opt${i}" class="field" required></label>`).join('')}
   <label>Correct option <select name="correct" class="field">${Array.from({length:4},(_,i)=>`<option value="${i}">${'ABCD'[i]}</option>`).join('')}</select></label>
   <label>Explanation (optional) <textarea name="explanation" class="field"></textarea></label>
   <p role="status" data-message></p>
   <button class="button">Add to Draft</button> <button type="button" data-close>Cancel</button>
   </form>`;
  const form=dialog.querySelector('form'),f=form.elements,message=dialog.querySelector('[data-message]');
  function sections(){
   const t=available.find(t=>t.id===Number(f.test.value));
   f.topic.replaceChildren(...t.sections.map(s=>new Option(s.topic,s.topic)));
  }
  f.test.onchange=sections;
  sections();
  dialog.querySelector('[data-close]').onclick=()=>dialog.close();
  dialog.addEventListener('close',()=>dialog.remove());
  const generate=dialog.querySelector('[data-generate]');
  generate.onclick=async()=>{
   generate.disabled=true;message.textContent='Preparing options…';
   try{
    const result=await api('admin/paste-preview','POST',{stem:f.stem.value,answer:f.answer.value});
    result.options.forEach((option,i)=>{f['opt'+i].value=option});
    f.correct.value=result.correctIndex;
    message.textContent='Check all options and confirm the correct answer.';
   }catch(error){message.textContent=error.message}
   finally{generate.disabled=false}
  };
  form.onsubmit=async e=>{
   e.preventDefault();e.stopPropagation();
   const submit=form.querySelector('button:not([type])');
   submit.disabled=true;
   try{
    await api('admin/paste-draft','POST',{testId:Number(f.test.value),topic:f.topic.value,stem:f.stem.value,options:Array.from({length:4},(_,i)=>f['opt'+i].value),correctIndex:Number(f.correct.value),explanation:f.explanation.value});
    dialog.close();await refreshStudio();alert('Question added to the selected mock draft.');
   }catch(error){message.textContent=error.message}
   finally{submit.disabled=false}
  };
  document.body.append(dialog);dialog.showModal();
 }catch(error){alert(error.message)}
});

root.addEventListener('click',event=>{
 if(!event.target.closest('[data-bulk-paste]'))return;
 const targetId=event.target.closest('[data-bulk-paste]').dataset.targetMock;
 const dialog=document.createElement('dialog');dialog.style.cssText='width:min(950px,95vw);max-height:90vh;overflow:auto';
 const sample='Section: Computer\nQ1. CPU का पूरा नाम क्या है?\nA) Central Processing Unit\nB) Central Program Utility\nC) Computer Processing User\nD) Control Program Unit\nAnswer: A\nExplanation: CPU निर्देशों को process करता है।\n\nQ2. इनमें से input device कौन सा है?\nA) Monitor\nB) Printer\nC) Keyboard\nD) Speaker\nAnswer: C\nExplanation: Keyboard से data enter किया जाता है।';
 dialog.innerHTML=`<h2>📋 Paste Questions into Mock</h2><p>कहीं भी तैयार किए गए MCQs यहाँ paste करें। API / billing की जरूरत नहीं। पहले preview, फिर draft save और review करके publish करें।</p><form><label>Select saved mock<select name="targetMock" class="field"><option value="">Create a new mock from this paste</option>${(studioState?.mocks||[]).filter(t=>!t.published&&t.generated<t.question_count).map(t=>`<option value="${t.id}">${esc(t.exam_name)} — ${esc(t.title)} (${t.generated}/${t.question_count})</option>`).join('')}</select></label><div class="formgrid" data-new-fields><label>Exam<select name="examId" class="field">${examOpts()}</select></label><label>Mock title<input name="title" class="field" required maxlength="200"></label><label>Type<select name="type" class="field"><option>Mini</option><option>Full</option><option>Subject</option><option>Topic</option><option>Sectional</option></select></label><label>Time (minutes)<input name="minutes" type="number" min="1" max="500" value="30" class="field" required></label><label>Correct marks<input name="positive" type="number" min="0.01" step="any" value="1" class="field" required></label><label>Wrong deduction<input name="negative" type="number" min="0" step="any" value="0" class="field" required></label></div><label>Subject / Section (if no Section heading)<input name="topic" class="field" value="General" required></label><details><summary>Paste format / Example</summary><pre style="white-space:pre-wrap">${esc(sample)}</pre><p>Number questions as Q1. or 1. Put each option on its own line. Use Section: Reasoning to start another section. Answer: A/B/C/D is required. Explanation is optional. Plain text only.</p><button type="button" data-example class="button ghost">Use example</button></details><label>All questions<textarea name="text" class="field" rows="14" placeholder="Q1. Question…&#10;A) …&#10;B) …&#10;C) …&#10;D) …&#10;Answer: B&#10;Explanation: …" required></textarea></label><p class="muted">Count and section distribution are taken from your paste; this does not verify official syllabus or factual answers. Default is one common timer; sectional timing can be edited before publishing. Exact duplicates and repeated numeric templates are checked; paraphrased repeats need your review.</p><button type="button" class="button" data-preview>Preview Questions</button> <button class="button" data-save disabled>Save Questions to Draft</button> <button type="button" data-close>Close</button><p data-status role="status"></p><div data-results></div></form>`;
 const form=dialog.querySelector('form'),f=form.elements,save=dialog.querySelector('[data-save]'),preview=dialog.querySelector('[data-preview]'),status=dialog.querySelector('[data-status]'),results=dialog.querySelector('[data-results]');let version=0;
 form.addEventListener('input',()=>{version++;save.disabled=true;status.textContent='Text/settings changed — preview again.'});
 dialog.querySelector('[data-example]').onclick=()=>{f.text.value=sample;version++;save.disabled=true};
 dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();
 const selectTarget=()=>{const t=studioState?.mocks.find(t=>t.id===+f.targetMock.value);dialog.querySelector('[data-new-fields]').hidden=!!t;for(const name of ['examId','title','type','minutes','positive','negative']){f[name].required=!t;if(t)f[name].value=({examId:t.exam_id,title:t.title,type:t.type,minutes:t.minutes,positive:t.positive,negative:t.negative})[name]}version++;save.disabled=true};f.targetMock.onchange=selectTarget;if(targetId){f.targetMock.value=targetId;selectTarget()};
 const payload=()=>({...Object.fromEntries(new FormData(form)),examId:+f.examId.value,minutes:+f.minutes.value,positive:+f.positive.value,negative:+f.negative.value});
 preview.onclick=async()=>{const snapshot=version;preview.disabled=true;save.disabled=true;status.textContent='Checking questions…';try{const r=await api('admin/bulk-preview','POST',payload());if(snapshot!==version){status.textContent='Text changed — preview again.';return}status.textContent=`${r.questions.length} questions · ${r.errors.length} errors`;results.innerHTML=`${r.errors.length?`<div class="notice">${r.errors.map(esc).join('<br>')}</div>`:''}<p>${r.warnings.map(esc).join(' · ')}</p><p>${r.sections.map(s=>esc(s.topic)+': '+s.count).join(' · ')}</p>${r.questions.map((q,i)=>`<details><summary>Q${i+1}. ${esc(q.stem)} · Answer ${'ABCD'[q.correctIndex]||'?'}</summary><p>${esc(q.topic)}</p>${q.options.map((o,j)=>`<p>${'ABCD'[j]}) ${esc(o)} ${j===q.correctIndex?'✓':''}</p>`).join('')}<p>${esc(q.explanation)}</p></details>`).join('')}`;save.disabled=!!r.errors.length}catch(e){status.textContent=e.message}finally{preview.disabled=false}};
 form.onsubmit=async e=>{e.preventDefault();e.stopPropagation();if(save.disabled)return;save.disabled=true;try{const r=await api(f.targetMock.value?'admin/bulk-append':'admin/bulk-create','POST',{...payload(),testId:+f.targetMock.value});dialog.close();await reload();alert(`${r.count} questions saved in draft. Open Review Queue → Preview / Edit Questions → Review & Publish.`)}catch(e){status.textContent=e.message;save.disabled=true}};
 document.body.append(dialog);dialog.showModal();
});

root.addEventListener('click',event=>{
 const button=event.target.closest('[data-add-exam],[data-new-manual]');if(!button)return;
 const isExam=button.hasAttribute('data-add-exam'),d=document.createElement('dialog');d.style.cssText='width:min(650px,94vw);max-height:90vh;overflow:auto';
 d.innerHTML=`<h2>${isExam?'Add New Exam':'Create New Mock'}</h2><form>${isExam?`<label>Exam name<input class="field" name="name" required maxlength="150"></label><label>Category<select class="field" name="category">${['SSC','Railway','Banking','Police','Teaching','Nursing','Computer Exams','Defence','State','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label>`:`<label>Exam<select class="field" name="examId">${examOpts()}</select></label><label>Mock name<input class="field" name="title" required maxlength="200"></label><label>Type<select class="field" name="type">${['Full','Mini','Subject','Topic','Sectional'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Total questions<input class="field" name="questionCount" type="number" min="1" max="500" value="20" required></label><label>Minutes<input class="field" name="minutes" type="number" min="1" max="500" value="20" required></label><label>Correct marks<input class="field" name="positive" type="number" min="0.01" step="any" value="1" required></label><label>Wrong deduction<input class="field" name="negative" type="number" min="0" step="any" value="0" required></label><p>Save करके इस mock में questions paste करें। पूरा question count होने पर publish कर सकेंगे।</p>`}<p role="status"></p><button class="button">${isExam?'Save Exam':'Save Mock'}</button> <button type="button" data-close>Cancel</button></form>`;
 d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();e.stopPropagation();const submit=d.querySelector('button:not([type])');submit.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await api(isExam?'admin/exams':'admin/manual-mock','POST',data);d.close();await reload();alert(isExam?'Exam saved. अब Create Mock में इसे चुनें।':'Mock saved. उसके Add Questions button से paste करें।')}catch(err){d.querySelector('[role=status]').textContent=err.message;submit.disabled=false}};
 document.body.append(d);d.showModal();
});
